#include <bits/stdc++.h>
#include <atcoder/modint>
using namespace std;
using namespace atcoder;

using mint = modint998244353;

#define ll long long
#define rep(i, n) for(int i = 0; i < n; ++i)
#define N (int)2e+5

vector<int>e[N];
ll c[N];
ll d[N];
mint ans;

ll dfs(int k){
	int sz=e[k].size();
	ll s=c[k];
	for(int i=0;i<sz;i++)s+=dfs(e[k][i]);
	if(s<d[k])ans=0;
	else{ //binom (s,d[k])
		rep(i,d[k]){
			ans*=mint(s-i);
			ans*=mint(i+1).inv();
		}
	}
	return (s-d[k]);
}

int main(void){
	int n,x;

	cin>>n;
	for(int i=1;i<n;i++){
		cin>>x;
		e[x-1].push_back(i);
	}
	rep(i,n)cin>>c[i];
	rep(i,n)cin>>d[i];

	ans=1;
	dfs(0);
	cout<<ans.val()<<endl;

	return 0;
}
